import { expect, it } from "vitest";
import { MemoryFileSystem } from "@poe-code/safe-fs/core";
import { runConvertCli, runConvertCliSync } from "./index.js";

// Independently generated by native ImageMagick from PPM pixels 208040ff2200.
const native = `# ImageMagick pixel enumeration: 2,1,0,255,cmyk
0,0: (191,0,128,127)  #BF00807F  cmyk(191.25,0,127.5,127)
1,0: (0,221,255,0)  #00DDFF00  cmyk(0,221,255,0)
`;
for (const mode of ["buffered", "retained", "sync"] as const) {
  it.each([false, true])(`decodes native CMYK TXT through ${mode}, alpha=%s`, async alpha => {
    const text = alpha ? `# ImageMagick pixel enumeration: 2,1,0,65535,cmyka
0,0: (49151,0,32768,32639,32896)
1,0: (0,56797,65535,0,0)
` : native;
    const bytes = new TextEncoder().encode(text), files = new Map([["/in.txt", bytes]]), filesystem = new MemoryFileSystem();
    await filesystem.writeFile("/in.txt", bytes);
    const args = ["/in.txt", "-colorspace", "sRGB", "-depth", "8", `${alpha ? "rgba" : "rgb"}:/out`];
    const result = mode === "sync" ? runConvertCliSync(args, files) : await runConvertCli(args, mode === "retained" ? { filesystem, cwd: "/" } : files);
    expect(result).toMatchObject({ exitCode: 0, stderr: "" });
    const output = mode === "retained" ? await filesystem.readFile("/out") : files.get("/out");
    expect(Array.from(output as Uint8Array)).toEqual(alpha ? [32,128,64,128,255,34,0,0] : [32,128,64,255,34,0]);
  });
}
